# -*- coding: utf-8 -*-
import json, re, glob
AQ = '/tmp/claude-0/-home-user-Pruebas/978f574d-1019-54bc-bb45-9f4fddd102bb/scratchpad/aq'
D = {}
for p in glob.glob(AQ + '/A*/passages.json'):
    d = json.load(open(p, encoding='utf8'))
    if isinstance(d, dict): d = d['items']
    for r in d: D[r['id']] = r
def _cut(t, a, b):
    if a: t = t[t.index(a):]
    if b: t = t[:t.index(b) + len(b)]
    return t
def clean(t): return re.sub(r'\s+', ' ', re.sub(r'\s*\(\d+\)', '', t)).strip()
def G(i, a=None, b=None): return clean(_cut(D[i]['greek'], a, b))
def EN(i, a=None, b=None): return clean(_cut(D[i]['english'], a, b))
OT = 'Griego: Otto 1857 vol. 7 (Jena), leído por un investigador en el escaneo'
OTV = 'Griego: Otto 1857 vol. 7; la página la vi yo en imagen (capturas AT19)'
def Q(i, lang, txt, es, ref, src): return dict(id=i, lang=lang, txt=txt, es=es, ref=ref, src=src)
S = []
def add(id, title, sub, quotes, res): S.append(dict(id=id, title=title, sub=sub, quotes=quotes, res=res))

add('AT01', 'Quién es Atenágoras y qué obras son suyas', 'Dos obras; ninguna lo nombra Eusebio',
 [Q('A11-05','en',EN('A11-05'),'Atenágoras fue el primero en dirigir la escuela de Alejandría; floreció en tiempos de Adriano y Antonino, a quienes también dirigió su discurso-Embajada en favor de los cristianos: un hombre que vivía como cristiano con el manto mismo de los filósofos y estaba al frente de la escuela académica.','Felipe de Side, Fragmento 2 (Cod. Barocc. 142)','Inglés: Eastbourne (tertullian.org); no leí el griego'),
  Q('A11-06','en',EN('A11-06'),'Una se halla en la obra de Metodio, Sobre la resurrección del cuerpo, conservada por Epifanio (Haer. 64) y por Focio (Bibl. 234). La otra noticia sobre él está en los escritos de Felipe de Side, en Panfilia, que floreció a principios del siglo V.','Nota introductoria, Ante-Nicene Christian Library','Inglés: ANCL (s. XIX); no leí Focio ni Epifanio')],
 '<b>Quién.</b> Filósofo cristiano ateniense, autor de la <i>Legación</i> (o <i>Súplica</i> en favor de los cristianos, 37 capítulos, a Marco Aurelio y Cómodo, hacia 176-180) y de <i>Sobre la resurrección de los muertos</i>. <b>Lo que se sabe poco:</b> las dos únicas noticias antiguas son Metodio (vía Epifanio y Focio) y Felipe de Side, del siglo V, que lo hace maestro en Alejandría y choca con Eusebio. <b>Negativo:</b> Eusebio <b>no nombra a Atenágoras</b> en los libros 1-9 de la <i>Historia eclesiástica</i> (sí a Cuadrato y Arístides, 4.3; el libro 10 no cargó) y Jerónimo no le dedica capítulo en <i>De viris illustribus</i>. El códice de París gr. 451 (914), escrito por el notario Baanes para Aretas, conserva las dos obras. <b>Límite:</b> el apartado de Focio lo cito de segunda mano (no abrí el códice 234).')

add('AT02', 'Legación 4 y 6: «todo hecho por medio de su Verbo» y «sostenido por su Espíritu»', 'El Verbo y el Espíritu como agencia de Dios, sin nombre de Hijo',
 [Q('A1-02','gr',G('A1-02'),'Pero como nuestra razón conduce a un solo Dios, hacedor de este universo, a él mismo no hecho (pues lo que es no llega a ser, sino lo que no es), pero que todo lo hizo por medio del Verbo que viene de él, en ambas cosas padecemos sin razón y se habla mal de nosotros y se nos persigue.','Legación 4 (Otto 1857, p. 22)',OT),
  Q('A1-05','gr',G('A1-05'),'Si, pues, Platón no es ateo por concebir un solo Dios ingénito, artífice del universo, tampoco nosotros somos ateos, que sabemos y sostenemos que es Dios aquel por quien todo ha sido hecho por el Verbo y es mantenido por el Espíritu que viene de él.','Legación 6 (Otto 1857, p. 30)',OT)],
 '<b>Qué dice.</b> El Verbo y el Espíritu son «de él» (<i>par\' autoû</i>) y son el modo en que Dios hace y mantiene todo. <b>Objeción.</b> Es un dativo de agencia, sin «persona» ni «Hijo»; arrianos, unitarios y sabelianos pueden leerlo. <b>Respuesta.</b> Es el lenguaje que Atenágoras usa para defenderse de la acusación de ateísmo ante filósofos: aún no habla de la persona del Hijo (lo hará en el capítulo 10). Lo importante es el <b>par «Verbo… Espíritu»</b>, que reaparece en 10, 12 y 24 desarrollado. <b>Límite.</b> En 1-9 «Hijo» no aparece; no se debe leer aquí una doctrina trinitaria.')

add('AT03', 'Legación 8 y 9: Dios «indivisible», y el Espíritu «como un flautista sopla en la flauta»', 'Las dos primeras objeciones: simplicidad y Espíritu-instrumento',
 [Q('A1-09','gr',G('A1-09'),'Pues no porque sean dioses son semejantes, sino que por ser ingénitos no son semejantes: lo generado es semejante a los modelos, lo ingénito es disímil […]. Pero Dios es ingénito, impasible e indivisible, no compuesto, pues, de partes.','Legación 8 (Otto 1857, p. 38)',OT),
  Q('A1-10','gr',G('A1-10'),'Puesto que las voces de los profetas confirman nuestros razonamientos […], quienes, movidos por el Espíritu divino según el éxtasis de sus pensamientos, proclamaron lo que se obraba en ellos, sirviéndose el Espíritu de ellos como un flautista sopla en una flauta, ¿qué dicen, pues, éstos?','Legación 9 (Otto 1857, p. 42)',OT)],
 '<b>Objeción A (Leg. 8).</b> Si Dios es «indivisible» y «no compuesto de partes», ¿cómo caben Verbo y Espíritu distintos? <b>Respuesta.</b> Atenágoras argumenta aquí contra <b>pluralidad de dioses</b>, no sobre distinciones internas; la tradición posterior responde con que en Dios <b>no hay partes</b> pero sí relaciones (Aquino, ST I q.27: la procesión del Verbo no es la de un efecto; ver AT17).<br><b>Objeción B (Leg. 9).</b> «Como un flautista»: modelo mecánico de inspiración. <b>Respuesta.</b> Es una <b>analogía</b> (<i>hōsei</i>, «como») sobre el modo de inspirar a los profetas, no una definición del Espíritu; y en el mismo pasaje el Espíritu «mueve» y «se sirve» (<i>kinḗsantos… synchrēsamenou</i>): es agente. Bethune-Baker (p. 46) la considera inspiración «mecánica y de origen pagano». <b>Límite.</b> Es el texto más usado contra un Espíritu personal.')

add('AT04', 'Pasaje difícil A (Legación 10): «el Hijo de Dios es el Verbo del Padre en idea y en operación»', 'Con la página real de Otto (captura AT19)',
 [Q('A2-01','gr',G('A2-01'),'Que no somos ateos, pues, honrando a un solo Dios, ingénito, eterno, invisible, impasible, incomprensible, inabarcable, que sólo con la mente y la razón se capta, rodeado de luz, belleza, espíritu y poder inefable, por quien el todo fue hecho por medio de su mismo Verbo, ordenado y mantenido, me parece suficientemente demostrado.','Legación 10.1 (Otto 1857, p. 44)',OT),
  Q('A2-02','gr',G('A2-02'),'Pues concebimos también un Hijo de Dios. Y que nadie juzgue ridículo que Dios tenga un Hijo. Pues no pensamos acerca de Dios Padre ni acerca del Hijo como los poetas que fabulan mitos, mostrando a los dioses en nada mejores que los hombres.','Legación 10.1 (Otto 1857, p. 44)',OT),
  Q('A2-03','gr','τοῦ θεοῦ λόγος τοῦ πατρὸς ἐν ἰδέᾳ καὶ ἐνεργείᾳ· πρὸς αὐτοῦ γὰρ καὶ δι᾽ αὐτοῦ πάντα ἐγένετο, ἑνὸς ὄντος τοῦ πατρὸς καὶ τοῦ υἱοῦ. Ὄντος δὲ τοῦ υἱοῦ ἐν πατρὶ καὶ πατρὸς ἐν υἱῷ, ἑνότητι καὶ δυνάμει πνεύματος, νοῦς καὶ λόγος τοῦ πατρὸς ὁ υἱὸς τοῦ θεοῦ.','[…] el Hijo de Dios es el Verbo del Padre en idea y en operación; pues según él y por él todo fue hecho, siendo uno el Padre y el Hijo. Y estando el Hijo en el Padre y el Padre en el Hijo, por unidad y poder de espíritu, mente y razón del Padre es el Hijo de Dios.','Legación 10.2 (Otto 1857, p. 46; captura AT19)',OTV)],
 '<b>Por qué es difícil.</b> «Idea y operación» (<i>en idéa kaì energeíā</i>) puede leerse como un atributo o plan de Dios, no un Hijo personal; Newman (<i>Arians</i>, p. 171) advierte que la metáfora «tendía a borrar la personalidad del Hijo, esto es, a introducir el sabelianismo». <b>Resolución.</b> (1) El mismo texto lo llama <b>«Hijo»</b> (<i>hyiós</i>, <i>paîs</i>) y dice «el Padre y el Hijo siendo <b>uno</b>» y «el Hijo <b>en</b> el Padre y el Padre <b>en</b> el Hijo»: inhabitación mutua entre dos distintos (Basilio, <i>De Spir. Sancto</i> 18.45: «el Hijo está en el Padre y el Padre en el Hijo»). (2) «Idea» es el <b>ejemplar</b> en la mente divina (Aquino, ST I q.15) y la «operación» su eficacia; Aquino (q.34 a.3) dice que el Verbo es a la vez «expresivo del Padre» y «operativo hacia las criaturas»: es el análogo tomista de «idea y operación». (3) Dorner (p. 283-284): Atenágoras «no permite que el ser del Hijo se agote en su relación con el mundo; le atribuye una relación previa con el Padre». <b>Límite.</b> Dorner añade que puede dudarse; Newman admite el riesgo sabeliano. La lectura nicena es relectura.')

add('AT05', 'Pasaje difícil B (Legación 10): «primer engendrado del Padre, no como hecho»… pero «salió» para crear', 'Mente eterna, Verbo eterno y «salida» hacia la materia',
 [Q('A2-05','gr','Εἰ δὲ δι᾽ ὑπερβολὴν συνέσεως σκοπεῖν ὑμῖν ἔπεισιν, ὁ παῖς τί βούλεται, ἐρῶ διὰ βραχέων· πρῶτον γέννημα εἶναι τῷ πατρί, οὐχ ὡς γενόμενον (ἐξ ἀρχῆς γὰρ ὁ θεός, νοῦς ἀΐδιος ὤν, εἶχεν αὐτὸς ἐν ἑαυτῷ τὸν λόγον, ἀϊδίως λογικὸς ὤν), ἀλλ᾽ ὡς τῶν ὑλικῶν ξυμπάντων, ἀποίου φύσεως καὶ γῆς ἀχρείας ὑποκειμένων δίκην, μεμιγμένων τῶν παχυμερεστέρων πρὸς τὰ κουφότερα ἐπ᾽ αὐτοῖς, ἰδέα καὶ ἐνέργεια εἶναι προελθών.','Pero si por exceso de inteligencia os place examinar qué es «el Hijo», lo diré brevemente: es el primer engendrado (<i>prôton génnēma</i>) del Padre, no como hecho (pues desde el principio Dios, siendo mente eterna, tenía en sí mismo al Verbo, siendo eternamente racional), sino como habiendo salido (<i>proelthṓn</i>) para ser idea y fuerza operante de todas las cosas materiales, que yacían a modo de naturaleza sin cualidades y de tierra inactiva, mezcladas las partes más pesadas con las más ligeras.','Legación 10.3 (Otto 1857, p. 46; captura AT19)',OTV)],
 '<b>Por qué es difícil.</b> «Primer engendrado» + «salió… para ser idea y fuerza de la materia» se lee como un nacimiento en el momento de crear (como en Teófilo y Taciano) o como una criatura primera. <b>Resolución, en cuatro pasos.</b> (1) <b>«No como hecho»</b> (<i>ouch hōs genómenon</i>): niega que sea criatura; Bull lo llama «un golpe mortal a la blasfemia arriana» (<i>Defensio</i>, p. 153). (2) <b>«Desde el principio… mente eterna… tenía en sí al Verbo, siendo eternamente racional»</b>: el Verbo es eterno en Dios; lo que «sale» es para la creación (<i>proelthṓn</i>): es la distinción verbo inmanente/proferido de Teófilo (ver el pack de Teófilo). Newman (p. 170): eterno en el Padre, con una «salida» para crear. (3) Atanasio (<i>Contra los arrianos</i> I.17): «si el Verbo no está con el Padre desde siempre, la Tríada no es eterna, sino que primero hubo una Mónada y después, por adición, una Tríada»; Agustín (<i>De Trin.</i> XV.23): el Verbo «igual al Padre, Dios de Dios, Luz de Luz». (4) «Primer engendrado» es una relación (de origen), no «primera criatura». <b>Límite.</b> Newman (p. 198): Atenágoras, Taciano, Teófilo, Hipólito y Novaciano «se han expuesto a este cargo» de que el Hijo comenzó con la creación; Dorner duda de que el Verbo sea inmanente. Es relectura.')

add('AT06', 'Pasaje difícil C (Legación 10): el Espíritu es una «efusión» (<i>apórroia</i>) de Dios', 'La imagen del rayo del sol que vuelve', 
 [Q('A2-07','gr',G('A2-07'),'Aunque también el Espíritu Santo mismo, que obra en los que hablan proféticamente, decimos que es una efusión (<i>apórroia</i>) de Dios, que fluye y vuelve como un rayo del sol.','Legación 10.4 (Otto 1857, p. 48; la vi en imagen)',OTV),
  Q('A10-11','en',EN('A10-11'),'Pues si fuera un Accidente, sería una Actividad de Dios, porque ¿qué otra cosa, o de quién otro, podría ser […]','Gregorio de Nacianzo, Or. 31.6','Inglés: Browne y Swallow, NPNF 2.ª serie vol. 7'),
  Q('A10-13','en',EN('A10-13'),'[…] como la raíz saca el árbol, y la fuente el río, y el sol el rayo […] el Espíritu es el tercero desde Dios y el Hijo; como […] el vértice del rayo es el tercero desde el sol.','Tertuliano, Adv. Praxean 8','Inglés: Holmes, ANF vol. 3')],
 '<b>Por qué es difícil.</b> «Efusión que fluye y vuelve» suena a una emanación impersonal: Loofs (§18, p. 126): «la personalidad del Espíritu es tan incierta como la de muchas potencias». Gregorio de Nacianzo plantea la alternativa de fondo: el Espíritu es <b>sustancia o accidente</b>; si accidente, mera actividad de Dios. <b>Resolución.</b> (1) Atenágoras habla del «Espíritu Santo <b>mismo</b>» (<i>autò… hágion pneûma</i>) que <b>obra</b> (<i>energoûn</i>) y lo enumera aparte: «Dios Padre, Hijo Dios y Espíritu Santo» (10.4). (2) Bull (p. 154) la lee como emanación consustancial («como la luz procede del fuego… reconoce la consustancialidad del Espíritu»); Bethune-Baker (p. 200): «implica la doctrina de su procesión esencial» y lo ve como «el vínculo de unión por el que el Padre y el Hijo coinhieren». (3) Tertuliano usa el mismo rayo del sol para el Espíritu «tercero desde Dios y el Hijo» (<i>Adv. Prax.</i> 8). (4) Atanasio (<i>C. Ar.</i> I.21) <b>rechaza</b> «cortes y efusiones» como imagen del Hijo y prefiere «resplandor» (<i>apaúgasma</i>, I.20): la tradición posterior corrige la metáfora. <b>Límite.</b> Atenágoras no resuelve la pregunta sustancia/accidente; Loofs y Dorner no ven allí persona clara.')

add('AT07', 'Pasaje difícil D (Legación 10 y 12): «su poder en la unión y su distinción en el orden»', 'Padre, Hijo y Espíritu con «unidad» y «distinción»',
 [Q('A2-09','gr',G('A2-09'),'¿Quién, pues, no se asombraría de oír llamar ateos a los que dicen Dios Padre, y Dios Hijo, y Espíritu Santo, mostrando tanto su poder en la unión como su distinción en el orden?','Legación 10.4 (Otto 1857, p. 48; la vi en imagen)',OTV),
  Q('A3-13','gr',G('A3-13'),'[…] cuál es la unidad del Hijo con el Padre, cuál la comunión del Padre con el Hijo, qué es el Espíritu, cuál la unión y distinción de los que así están unidos: el Espíritu, el Hijo, el Padre […]','Legación 12 (Otto 1857, p. 56)',OT)],
 '<b>Qué dice.</b> Tres nombres (<i>Theòn patéra… kaì hyiòn theón… kaì pneûma hágion</i>) con «unión» y «distinción»; en el cap. 12, «unidad del Hijo con el Padre… comunión… qué es el Espíritu… unión y distinción». <b>Objeción.</b> Loofs (p. 126): las fórmulas triádicas de los apologistas no son una doctrina de la Trinidad, sino «elasticidad filosófico-pagana de su monoteísmo». Atenágoras <b>no usa «tríada»</b> ni «consustancial», y en el cap. 12 sólo <b>plantea</b> las preguntas. Otto anota una variante manuscrita (puntuación tras <i>hyión</i>, que haría de «<i>theón</i>» el Espíritu). <b>Respuesta.</b> No es una lista: es una enumeración con <b>estructura</b> («unión» y «orden», <i>héndōsis</i> y <i>táxis</i>) que Basilio (<i>De Spir. Sancto</i> 18.45) retoma: «no contamos por adición… el Hijo está en el Padre y el Padre en el Hijo»; y Tertuliano (<i>Adv. Prax.</i> 2): «tres, no en condición sino en grado; no en sustancia sino en forma; no en poder sino en aspecto; pero de una sola sustancia, condición y poder». <b>Límite.</b> La unidad se expresa en «poder» (<i>dýnamis</i>), no en «esencia».')

add('AT08', 'La «unidad de espíritu» (Leg. 10.2) y el «unidos en poder» (Leg. 24): qué dice el griego y qué dice la ANF', 'El «unidos en esencia» de la ANF no está en el griego de Otto',
 [Q('A4-06','gr',G('A4-06'),'Pues así como decimos Dios, y su Hijo el Verbo, y Espíritu Santo, unidos en poder (<i>kata dýnamin</i>) el Padre, el Hijo, el Espíritu, porque el Hijo es mente, razón, sabiduría del Padre, y el Espíritu efusión como la luz del fuego, así también entendemos que hay otras potencias que dominan sobre la materia y por medio de ella […]','Legación 24 (Otto 1857, p. 124; captura AT20)','Griego: Otto 1857 p. 124; la página la vi yo en imagen (AT20)'),
  Q('A5-12','la',EN('A5-12', None, 'τὸν πατέρα etc.'),'En vano Gesner, a quien (como suele) sigue Rechenberg, preferiría leer: «tres en poder, unidos en esencia, el Padre…» (traducción mía; Otto lo llama «en vano»).','Otto, comentario latino, nota 6 a la p. 124 (en la p. 125)','Latín: Otto; el pasaje griego es una conjetura rechazada'),
  Q('A2-11','la',G('A2-11'),'Aquí el nombre «espíritu» no significa la persona del Espíritu Santo, sino la esencia espiritual del Padre y del Hijo […] es decir, la divinidad (Marano), «la esencia divina común» (Dorner).','Otto, nota 9 a Leg. 10 (p. 46; vista en imagen)','Latín y alemán: Otto; traducción mía')],
 '<b>Corrección importante.</b> La traducción inglesa (Pratten, ANF vol. 2, p. 141: «<i>united in essence</i>») <b>no está en el griego impreso</b>: éste dice «<b>unidos en poder</b>» (<i>kata dýnamin</i>), y «en esencia» es una <b>conjetura de Gesner</b> («tres en poder, unidos en esencia») que Otto rechaza. <b>No se puede citar a Atenágoras para <i>homoousios</i>.</b> <b>Segundo punto.</b> En 10.2 «unidad y poder de <i>pneûma</i>» ha sido leído por Clerc, Marano y Dorner como la <b>esencia divina común</b> (no la persona del Espíritu Santo), y por Bull como el Espíritu Santo. <b>Qué sí se sigue.</b> Padre, Hijo y Espíritu están unidos en un poder y se distinguen en un orden; el Hijo es «mente, razón, sabiduría» del Padre (el esquema de Teófilo), el Espíritu «efusión como luz del fuego». <b>Límite.</b> «Unidad en esencia» es doctrina niceno-constantinopolitana, no atribuible a este texto.')

add('AT09', 'Pasaje difícil E (Legación 10, 24): los ángeles y «ministros»; el Verbo como quien los ordena', '¿Es el Verbo un ángel más?',
 [Q('A5-01','gr',G('A5-01'),'[…] decimos también una multitud de ángeles y ministros, a quienes el Hacedor y Artífice del mundo, Dios, por medio de su Verbo, distribuyó y dispuso para estar alrededor de los elementos, los cielos y el mundo, y lo que hay en él, y su buen orden.','Legación 10 (Otto 1857, pp. 48-50)',OT),
  Q('A5-06','gr',G('A5-06'),'Pues ésta es la constitución de los ángeles: haber sido hechos por Dios para la providencia sobre lo ordenado por él, a fin de que Dios tenga la providencia total y general de todo, y la particular los ángeles puestos sobre ellas.','Legación 24 (Otto 1857, pp. 126-128)',OT),
  Q('A4-07','gr',G('A4-07'),'[…] es contrario el espíritu que ejerce su dominio sobre la materia, hecho por Dios como los demás ángeles, y encargado de la administración de la materia y de las formas de la materia.','Legación 24 (Otto 1857, p. 126)','Griego: Otto 1857 p. 126, verificado en imagen por un investigador')],
 '<b>Por qué es difícil.</b> Algunos lectores piensan que el «Hijo-Verbo» de Atenágoras es una potencia entre otras (como en Justino, ver su pack: «ángel»). <b>Resolución.</b> (1) Los ángeles son <b>creados por Dios por medio de su Verbo</b> (10): el Verbo es el agente que los ordena, <b>no uno de ellos</b>. (2) En 24 los ángeles son criaturas con «providencia particular»; Dios guarda la «providencia total y general». (3) Hasta el espíritu rebelde «fue hecho por Dios, como los demás ángeles». <b>Qué no dice.</b> No dice nada sobre la generación ni la divinidad del Verbo; el pasaje sólo <b>descarta que el Hijo sea ángel</b> al ponerlo como agente de Dios sobre ellos. Nota 11 de la ANF (Heb 1:14): los ángeles son «espíritus ministradores», no objetos de culto. <b>Límite.</b> Atenágoras llama «ministros» (<i>leitourgoí</i>) a los ángeles, no al Verbo.')

add('AT10', 'Legación 12 y 30: «conocer a Dios y a su Verbo», y «sólo el Dios ingénito es eterno»', 'La objeción «solo eterno» y su contexto',
 [Q('A3-12','gr',G('A3-12'),'[…] conducidos [a la vida futura] por esto solo: por conocer a Dios y a su Verbo […]','Legación 12 (Otto 1857, pp. 54-56)',OT),
  Q('A6-01','gr',G('A6-01'),'Que no somos ateos, pues, honrando como Dios al hacedor de este universo y a su Verbo, según mi capacidad, aunque no a la altura del asunto, ha quedado demostrado.','Legación 30, frase final (Otto 1857)',OT),
  Q('A6-02','gr',G('A6-02'),'[…] y si ves la cueva, te acuerdas del parto de Rea; y si ves el sarcófago, ensombreces al muerto, no sabiendo que sólo es eterno el Dios ingénito.','Legación 30 (Otto 1857)',OT+'; «[ὁ]» entre corchetes en el texto')],
 '<b>Qué dice.</b> «Conocer a Dios y a su Verbo» (12, eco de Jn 17:3) es la vida eterna; en 30 el cierre de la obra repite «Dios y su Verbo»: Verbo con Dios, sin Espíritu. <b>Objeción.</b> «Sólo (<i>mónos</i>) eterno (<i>aídios</i>) el Dios ingénito (<i>agénētos</i>)»: arrianos y unitarios lo oponen a un Hijo eterno. <b>Resolución.</b> (1) El <b>contexto</b> (cueva de Rea, sarcófago de Zeus) contrapone al Dios <b>no engendrado ni mortal</b> a los dioses nacidos y muertos de los mitos; no discute la relación Padre-Hijo. (2) El mismo autor dice en 10.3 que Dios, «mente eterna», tenía «en sí» al Verbo, «eternamente racional»: el Verbo no es otra cosa fuera de Dios. (3) El texto de «<i>agénētos</i>» lleva una nota de Otto (n. 22) que no pude revisar. <b>Límite.</b> La lectura nicena es contextual; las palabras literales («solo eterno») las citan los adversarios.')

add('AT11', 'Sobre la resurrección de los muertos: sin doctrina trinitaria', 'Una obra filosófica; autoría discutida',
 [Q('A7-05','gr',G('A7-05'),'Y si a los hombres se les ha dado también mente y razón para el discernimiento de lo inteligible, no sólo de las esencias sino también de la bondad, sabiduría y justicia del que las dio, es necesario que, permaneciendo aquello por lo cual se ha dado el juicio racional […]','Sobre la resurrección 15 (Otto 1857, p. 248)',OT),
  Q('A7-12','la',G('A7-12'),'El libro Περὶ ἀναστάσεως νεκρῶν se contiene en los tres códices antiquísimos (Par. 1, 2, Arg.) […]. El códice fue escrito por el notario Baanes, de Aretas arzobispo de Cesarea, el año de Cristo 914.','Otto, Prolegomena (PDF p. 18)','Latín: Otto; resumen mío, no traducción literal')],
 '<b>Qué dice.</b> «Mente y razón» (<i>noûs kaì lógos</i>) son facultades humanas en 15; las «naturalezas inteligibles» (<i>noētaì phýseis</i>, cap. 10) las identifica con ángeles sólo el aparato de Otto. <b>Resultado negativo.</b> No hay «Cristo», «Jesús», «Hijo», «Verbo» divino, «Espíritu Santo» ni «Trinidad» en el cuerpo del texto griego ni en la ANF: la obra es filosófica y antropológica; no sirve para el caso trinitario. <b>Autoría.</b> Los manuscritos la atribuyen a Atenágoras; Grant (<i>HTR</i> 47, 1954) argumenta contra su autoría (según un resumen que sólo leí por WebFetch). <b>Límite.</b> Lo que sigue se apoya únicamente en la <i>Legación</i>.')

add('AT12', 'Lo que Atenágoras NO dice (resultados negativos)', 'Búsqueda en el griego de Otto y en el inglés de la ANF',
 [],
 '<b>Resultados.</b> En la <i>Legación</i> y en <i>Sobre la resurrección</i>: <b>«Jesús»: 0 veces</b>; <b>«Cristo»: sólo «cristianos»</b> (Otto lo trae sólo en prolegómenos y aparato); <b>«Trinidad/tríada» (<i>trías</i>): 0 veces</b>; <b>«consustancial»: 0</b>; <b>«Espíritu Santo»</b> como nombre: 10 y 24 (y «espíritu divino» en 9); <b>«Hijo»</b>: 10, 12 (<i>paîs</i>), 18 (<i>hyiô noouméno</i>) y 24; <b>«Verbo»</b>: 4, 6, 10, 12, 18, 24 y 30. <b>Qué se sigue.</b> La <i>Legación</i> es una apología a los emperadores que presenta a Dios, al Verbo-Hijo y al Espíritu <b>sin hablar de Jesucristo</b>; por eso no se le puede pedir cristología. <b>Cautelas de lectura.</b> (1) ANF traduce «Verbo que procede de él» en 18; el griego dice sólo <i>par\' autoû</i>, «de él». (2) «Hijo» (<i>paîs</i>) de 10.3 puede ser «niño, siervo» en griego; el texto lo explica con «Hijo de Dios». <b>Límite.</b> Búsqueda por OCR en Otto y por texto en inglés; no revisé Migne.')

add('AT13', 'Lo que dicen los estudiosos (1): a favor de la intención ortodoxa', 'Bull, Newman, Bethune-Baker, Dorner',
 [Q('A9-01','en',EN('A9-01'),'Pero el Hijo de Dios es el Verbo del Padre, en idea y en operación. Pues por Él y por medio de Él todo fue hecho, siendo Uno el Padre y el Hijo; y estando el Hijo en el Padre y el Padre en el Hijo por la unidad y el poder del Espíritu: el Hijo de Dios es la mente y el Verbo de Dios. (Rendición inglesa de Bull)','Bull, Defensio fidei Nicaenae, II.4 (Oxford 1851, p. 152)','Inglés: Bull (trad. 1851)'),
  Q('A9-03','en',EN('A9-03'),'[…] el Espíritu Santo también fluye y emana del mismo Dios Padre (por el Hijo, es decir, como hemos mostrado antes) como la luz procede del fuego. De paso puedes observar con qué plenitud reconoció Atenágoras la consustancialidad del Espíritu Santo, igualmente que la del Hijo.','Bull, Defensio, p. 154','Inglés: Bull (trad. 1851)'),
  Q('A9-12','en',EN('A9-12'),'[…] Atenágoras, que ve en el Espíritu el vínculo de unión por el que el Padre y el Hijo coinhieren, e implica la doctrina de su procesión esencial por la imagen en que lo describe como una efusión de Dios, que emana de Él y vuelve a Él como un rayo del sol o como la luz del fuego.','Bethune-Baker, Introduction to the Early History of Christian Doctrine (1903), p. 200','Inglés: Bethune-Baker (Methuen)'),
  Q('A9-14','en',EN('A9-14'),'La representación de una hipostatización del Logos en la creación es rechazada por completo por el más claro y cauto Atenágoras, que, por su concepto más puro de Dios, abre el camino a una relación inmanente entre el Padre y el Hijo.','Dorner, History of the Development of the Doctrine of the Person of Christ, p. 283','Inglés: Alexander (T. & T. Clark, 1861)')],
 '<b>Qué muestra.</b> Bull (1685) y Newman (p. 170) leen «no como hecho» como golpe al arrianismo; Dorner ve una relación «inmanente» Padre-Hijo; Bethune-Baker ve en la efusión una «procesión esencial». <b>Cautelas.</b> (1) Bull es un abogado nicenista y su «<i>unidad y poder del Espíritu</i>» como Espíritu Santo es lectura suya (otros leen «esencia divina»: AT08). (2) La «relación inmanente» es categoría de Dorner, no de Atenágoras. (3) «Implica» es de Bethune-Baker; el escaneo no muestra que Atenágoras afirme un Espíritu-persona.')

add('AT14', 'Lo que dicen los estudiosos (2): las objeciones serias', 'Newman, Loofs y Dorner',
 [Q('A9-08','en',EN('A9-08'),'Los Padres que se han expuesto a este cargo son Atenágoras, Taciano, Teófilo, Hipólito y Novaciano, como se mencionó en el primer capítulo. Ahora, que no quisieron decir lo que un lector superficial podría imputarles, puede argumentarse, primero, por el lenguaje paralelo de los posnicenos […]','Newman, Arians of the Fourth Century, p. 198','Inglés: Newman (Longmans)'),
  Q('A9-07','en',EN('A9-07'),'Su tendencia obvia era borrar la noción de la Personalidad del Hijo, esto es, introducir el sabelianismo. […] Y para contrarrestar esta tendencia, esto es, para testimoniar contra ella, los Padres hablan de Él como el Verbo en una hipóstasis, el Verbo permanente, real y vivo.','Newman, Arians, p. 171','Inglés: Newman (Longmans)'),
  Q('A9-21','en',EN('A9-21'),'Atenágoras, que llama al Espíritu una «apórroia» de Dios, también lo distingue claramente del Logos […]. La personalidad del Espíritu es, por tanto, tan incierta como la de muchas potencias.','Loofs, Leitfaden §18 (5a), p. 126','Alemán: Loofs; traducción inglesa del investigador')],
 '<b>Lectura honesta.</b> (a) Newman admite que Atenágoras y otros «se han expuesto al cargo» de que el Hijo «comenzó» con la creación (generación vinculada al mundo), y que la metáfora «tendía al sabelianismo», que los posnicenos corrigieron con «hipóstasis». (b) Loofs duda de la personalidad del Espíritu en Atenágoras y de que las fórmulas triádicas sean doctrina trinitaria. (c) Dorner opina que «puede dudarse» si el ser del Hijo es algo más que ser «la idea del mundo» (pp. 283-284). <b>Mi posición.</b> No defiendo que Atenágoras formulara Nicea: defiendo que no es arriano ni un simple modalista, que llama «Hijo» al Verbo, lo hace «no hecho», «mente eterna» y enumera Padre-Hijo-Espíritu con «unión» y «orden», con un Espíritu no resuelto. <b>Pendiente:</b> Prestige, Kelly, Barnard, Grant, Behr y Schoedel no se pudieron abrir (restringidos).')

add('AT15', 'Cómo lo resuelve la teología posterior (1): Verbo eterno, «idea», sin criatura', 'Atanasio, Agustín, Aquino',
 [Q('A10-03','en',EN('A10-03'),'Pues si el Verbo no está con el Padre desde siempre, la Tríada no es eterna; sino que primero hubo una Mónada y después, por adición, se hizo Tríada […]','Atanasio, Contra los arrianos I.17','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('A10-04','en',EN('A10-04'),'[…] el Hijo es la Imagen y el Resplandor del Padre, y Expresión y Verdad','Atanasio, Contra los arrianos I.20','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('A10-17','en',EN('A10-17'),'El Verbo de Dios, pues, el Hijo unigénito del Padre, en todo semejante e igual al Padre, Dios de Dios, Luz de Luz, Sabiduría de Sabiduría, Esencia de Esencia […]','Agustín, De Trinitate XV.23','Inglés: Haddan, NPNF 1.ª serie vol. 3'),
  Q('A10-20','en',EN('A10-20'),'[…] el Verbo de Dios es sólo expresivo de lo que hay en Dios Padre, pero es a la vez expresivo y operativo de las criaturas; y por eso se dice (Sal 32:9): «Él habló, y fueron hechas».','Aquino, ST I q.34 a.3','Inglés: Dominicos ingleses (newadvent)')],
 '<b>Aplicación a Atenágoras (mía).</b> «Idea y operación» y «primer engendrado, no hecho, mente eterna» son la formulación del siglo II de lo que Aquino expresa distinguiendo en el Verbo lo <b>«expresivo del Padre»</b> (eterno, inmanente) y lo <b>«operativo hacia las criaturas»</b> (la creación). Atanasio responde a la lectura temporal: sin Verbo eterno no hay Tríada eterna. Y Agustín da la fórmula nicena que Atenágoras no tiene: «Dios de Dios… Esencia de Esencia». <b>Honestidad.</b> Ninguna de estas fuentes cita a Atenágoras; el Resplandor (<i>apaúgasma</i>) de Atanasio es el modelo que sustituye a la «efusión» (ver AT06). Aquino (q.34 a.3) no concilia con estas palabras el «salió» de Atenágoras. Todos los textos en inglés (newadvent, NPNF); no leí el griego ni el latín.')

add('AT16', 'Cómo lo resuelve la teología posterior (2): el Espíritu y la unidad en el orden', 'Gregorio de Nacianzo, Basilio, Tertuliano, Aquino',
 [Q('A10-05','en',EN('A10-05'),'Quienes, antes que confesar que el Hijo es la Imagen del Padre, conciben ideas materiales y terrenas del mismo Padre, atribuyéndole cortes y efusiones e influencias.','Atanasio, Contra los arrianos I.21','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('A10-09','en',EN('A10-09'),'Pues no contamos por adición, haciendo crecer gradualmente de la unidad a la multitud, y diciendo uno, dos y tres, ni tampoco primero, segundo y tercero. […] Pues el Hijo está en el Padre y el Padre en el Hijo','Basilio, De Spiritu Sancto 18.45','Inglés: Jackson, NPNF 2.ª serie vol. 8'),
  Q('A10-14','en',EN('A10-14'),'tres, sin embargo, no en condición sino en grado; no en sustancia sino en forma; no en poder sino en aspecto; pero de una sola sustancia, y de una sola condición, y de un solo poder','Tertuliano, Adv. Praxean 2','Inglés: Holmes, ANF vol. 3')],
 '<b>Aplicación a Atenágoras (mía).</b> Atanasio rechaza «cortes y efusiones» como imagen divina; Basilio y Tertuliano dan la doctrina de «unidad y distinción» que en Atenágoras queda como «unión en poder y distinción en orden»: no se cuenta «por adición», el Hijo está «en» el Padre (la frase de Atenágoras en 10.3). Gregorio (Or. 31.6) responde a «Espíritu = actividad». <b>Límite.</b> Estos textos no comentan a Atenágoras; el Espíritu como «tercero desde Dios y el Hijo» (Tertuliano) es doctrina posterior que Atenágoras aún no formula.')

add('AT17', 'Paralelos: Atenágoras no está solo', 'Justino, Taciano, Teófilo, Ireneo',
 [Q('A11-11','en',EN('A11-11'),'Que lo adoramos con razón, habiendo aprendido que es el Hijo del Dios verdadero mismo, y teniéndolo en segundo lugar, y al Espíritu profético en el tercero, lo demostraremos.','Justino, 1 Apología 13','Inglés: Dods y Reith, ANF vol. 1'),
  Q('A11-12','en',EN('A11-12'),'Dios estaba en el principio; pero el principio, hemos aprendido, es el poder del Logos […] por su simple voluntad el Logos brota; y el Logos, no saliendo en vano, viene a ser la obra primogénita del Padre […] Vino a ser por participación, no por abscisión','Taciano, Oración 5','Inglés: Ryland, ANF vol. 2'),
  Q('A11-13','en',EN('A11-13'),'Dios, pues, teniendo a su propio Verbo interno dentro de sus propias entrañas, lo engendró, emitiéndolo junto con su sabiduría antes de todas las cosas.','Teófilo, A Autólico 2.10','Inglés: Dods, ANF vol. 2'),
  Q('A11-16','en',EN('A11-16'),'He demostrado también ampliamente que el Verbo, es decir, el Hijo, estaba siempre con el Padre; y que la Sabiduría también, que es el Espíritu, estaba presente con Él, antes de toda creación.','Ireneo, Adv. haer. 4.20.3','Inglés: Roberts y Rambaut, ANF vol. 1')],
 '<b>Qué muestra.</b> Atenágoras comparte el vocabulario común del siglo II: el Verbo «en segundo lugar» y el Espíritu «en tercero» (Justino), el Verbo «que brota» (Taciano), el Verbo interno luego proferido (Teófilo), Verbo y Sabiduría/Espíritu «siempre con él» (Ireneo). <b>Cautelas.</b> Taciano llama al Verbo «obra primogénita» (término de aire criatural); Teófilo habla de generación al crear; nadie en este grupo dice «consustancial». <b>Diferencia propia de Atenágoras.</b> Es el único de estos autores que insiste en «no como hecho» y «mente eterna… eternamente racional» (10.3). Los packs de Justino y Teófilo están en la misma carpeta.')

add('AT18', 'Resumen de pasajes difíciles y cómo se resuelven', 'Veredicto honesto: trinitario «en intención», con un Espíritu no resuelto', [], '__TABLE__')
